            wire center = q_reg[i];
            wire right = (i == 511) ? 1'b0 : q_reg[i+1];

            // Rule 110: next state = 1 for all cases except (1,1,1) and (1,0,0)
            // Which is equivalent to: !(left & center & right) & !(left & ~center & ~right)
            // Or more simply: ~(left & center & right) & ~(left & ~center & ~right)
            // But we can use a case statement or direct expression.
            // Alternatively, known expression for Rule 110: next = (left | center) & ~(left & center & right) | (~left & center & ~right);
            // However, simplest is to use the truth table:
            // next = (~left & center & ~right) | (~left & center & right) | (~left & ~center & right) | (left & ~center & right) | (left & center & ~right);
            // But we can simplify: Rule 110 is equivalent to: next = (left | center) & ~(left & center & right) | (~left & ~center & right);
            // Actually, standard minimal expression: next = ~(left & center & right) & (left | center | right);
