module TopModule (
    input clk,
    input areset,
    input predict_valid,
    input [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,
    input train_valid,
    input train_taken,
    input train_mispredicted,
    input [6:0] train_history,
    input [6:0] train_pc
);

    // 7-bit global history register
    reg [6:0] ghr;

    // Pattern History Table: 128 entries, each a 2-bit saturating counter
    reg [1:0] pht [0:127];

    // Internal signals
    wire [6:0] predict_index = predict_pc ^ ghr;
    wire [6:0] train_index = train_pc ^ train_history;

    // Prediction logic: taken if counter >= 2 (i.e., 2'b10 or 2'b11)
    assign predict_taken = (pht[predict_index] >= 2'b10);
    assign predict_history = ghr;

    // Sequential logic: updates on positive clock edge, asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'b0;
            // Initialize all PHT entries to weakly not taken (2'b01)
            integer i;
            for (i = 0; i < 128; i = i + 1) begin
                pht[i] <= 2'b01;
            end
        end else begin
            // Training takes precedence over prediction for GHR update
            if (train_valid) begin
                // Update GHR based on actual outcome (train_taken)
                ghr <= {ghr[5:0], train_taken};

                // Update PHT entry based on actual outcome
                if (train_taken) begin
                    // Increment saturating counter (max 3)
                    if (pht[train_index] != 2'b11) begin
                        pht[train_index] <= pht[train_index] + 2'b01;
                    end
                end else begin
                    // Decrement saturating counter (min 0)
                    if (pht[train_index] != 2'b00) begin
                        pht[train_index] <= pht[train_index] - 2'b01;
                    end
                end
            end else if (predict_valid) begin
                // Update GHR based on predicted outcome (predict_taken)
                ghr <= {ghr[5:0], predict_taken};
            end
            // If neither valid, GHR and PHT remain unchanged
        end
    end

endmodule
